self.addEventListener("push",i=>{if(i.data)try{let t=i.data.json(),n=t.title||"Staff Guru Notification",o={body:t.body||"",icon:t.icon||"/icons/icon-192x192.png",badge:t.badge||"/icons/icon-192x192.png",data:{url:t.url||"/dashboard"},tag:t.tag||"staff-guru",renotify:!0,vibrate:[200,100,200]};i.waitUntil(self.registration.showNotification(n,o))}catch(i){console.error("[ServiceWorker] Failed to display push notification:",i)}}),self.addEventListener("notificationclick",i=>{var t;i.notification.close();let n=(null===(t=i.notification.data)||void 0===t?void 0:t.url)||"/dashboard";i.waitUntil(self.clients.matchAll({type:"window",includeUncontrolled:!0}).then(i=>{for(let t of i)if("focus"in t&&t.url.includes(n))return t.focus();if(self.clients.openWindow)return self.clients.openWindow(n)}))});